function homeImmersive(){const c=cat(),level=Math.floor(c.xp/100)+1;return `
<div class="room-welcome"><div class="eyebrow"><span class="live-dot"></span> YOUR LITTLE HAPPY PLACE</div><h1>The sunny corner.</h1><p>A warm room. Your favorite little company.</p><div class="room-tools"><button id="reset-view" title="Reset camera view">${icon('home')}Reset view</button><button id="sound-toggle" aria-pressed="${cafeRoom?.soundEnabled||false}">${icon('heart')}Sound ${cafeRoom?.soundEnabled?'on':'off'}</button></div></div>
<div id="speech" class="world-speech">${c.sick?'A little care would help. ♡':'Oh, there you are. ♡'}</div>
<div class="room-hint" id="room-hint">${icon('switch')}<span>Drag the room to look around <b>·</b> Stroke your cat to hear a purr</span></div>
<aside class="floating-status glass"><div class="panel-heading"><h2>A little check-in</h2><span class="status-chip ${c.sick?'sick':''}">● ${c.sick?'Needs care':'Feeling good'}</span></div><div class="status-list">${stat('Full tummy','hunger','#c9ad79','food')}${stat('Happiness','happiness','#cda59a','heart')}${stat('Energy','energy','#a9b387','moon')}${stat('Health','health','#95af99','health')}</div><div class="mini-bond">${icon('heart')}<span>Level ${level} · ${level<3?'Getting to know you':'Best of friends'}</span><span>${c.xp%100}/100</span></div><div class="bar"><i style="width:${c.xp%100}%;background:#a4b38a"></i></div>${c.sick?`<button class="care-kit-link" data-care="medicine">${icon('health')}Medicine & recovery care →</button>`:''}</aside>
<section class="floating-joys glass"><div class="panel-heading"><h2>Today’s little joys</h2><span>${[state.daily.pet,state.daily.feed,state.daily.play].filter(Boolean).length}/3</span></div><div class="joy-icons">${[['pet','heart','Pet'],['feed','food','Feed'],['play','wand','Play']].map(([k,i,l])=>`<span class="${state.daily[k]?'done':''}">${icon(state.daily[k]?'check':i)}${l}</span>`).join('')}</div><button class="btn full light" id="daily-claim" ${!allDaily()||state.daily.claimed?'disabled':''}>${state.daily.claimed?'Reward collected ✓':'Daily reward · 30 coins'}</button></section>
<div class="quick-games"><button class="glass quick-game" data-game="memory">${icon('game')}<span>Purrfect pairs<small>Earn 35 coins</small></span><span>↗</span></button><button class="glass quick-game" data-game="catch">${icon('spark')}<span>Treat catcher<small>Up to 60 coins</small></span><span>↗</span></button><button class="cafe-shortcut" data-go="cafe">${icon('cup')}Your café card ↗</button></div>
<section class="companion-dock glass"><div class="dock-title"><div><h2>${esc(c.name)} <span>${c.sick?'Needs care':'Your companion'}</span></h2><p>${esc(c.bio)}</p></div><button class="text-button" data-go="cats" aria-label="Switch cat">${icon('switch')}</button></div><div class="care-actions"><button class="action" data-care="pet"><span class="action-icon">${icon('heart')}</span>Pet</button><button class="action" data-care="feed"><span class="action-icon">${icon('food')}</span>Feed</button><button class="action" data-care="play" ${c.sick?'disabled':''}><span class="action-icon">${icon('wand')}</span>Play</button><button class="action" data-care="rest"><span class="action-icon">${icon('moon')}</span>Rest</button></div></section>`}
